function RankBadge({ referralCount }) {
  const rank = getRank(referralCount);
  const next = getNextRank(referralCount);
  const needed = next ? Math.max(0, next.minReferrals - referralCount) : 0;
  return (
    <View style={[ProfileStyles.rankCard, { borderColor: rank.color + '33' }]}>
      <View style={[ProfileStyles.rankCardBg, { backgroundColor: rank.color + '11' }]} />
      <Text style={ProfileStyles.rankIcon}>{rank.icon}</Text>
      <Text style={ProfileStyles.rankLabel}>{rank.label}</Text>
      <Text style={[ProfileStyles.rankValue, { color: rank.color }]}>{referralCount || 0}</Text>
      {next && <Text style={ProfileStyles.rankSubtext}>{needed} more to {next.label}</Text>}
    </View>
  );
}
function ReferralCodeCard({ referralCode, onCopy }) {
  return (
    <View style={ProfileStyles.referralCard}>
      <View style={ProfileStyles.referralLeft}>
        <Text style={ProfileStyles.referralLabel}>My Referral Code</Text>
        <Text style={ProfileStyles.referralCode}>{referralCode || 'Generating...'}</Text>
        <Text style={ProfileStyles.referralHint}>Share this code to earn referral bonus</Text>
      </View>
      <TouchableOpacity style={ProfileStyles.copyBtn} onPress={onCopy} disabled={!referralCode}>
        <Feather name="copy" size={16} color="#fff" />
        <Text style={ProfileStyles.copyBtnText}>Copy</Text>
      </TouchableOpacity>
    </View>
  );
}

// SimpleDropdown removed (photo-only updates)
function SavedProfileCard({ profile }) {
  const fields = [
    { icon:'user',        label:'Full Name',         value:profile.name,              accent:'#7d38ff' },
    { icon:'mail',        label:'Email Address',      value:profile.email,             accent:'#22aaf3' },
    { icon:'map-pin',     label:'State',              value:profile.state,             accent:'#f97316' },
    { icon:'home',        label:'Village',            value:profile.village,           accent:'#ff6f91' },
    { icon:'phone',       label:'Phone Number',       value:profile.phone_number,      accent:'#1ec9b0' },
    { icon:'smartphone',  label:'Mobile Number',      value:profile.mobile_number || profile.contact_number, accent:'#14b8a6' },
    { icon:'star',        label:'Subscription Type',  value:profile.subscription_type, accent:'#eab308' },
    { icon:'file-text',   label:'Bio',                value:profile.bio,               accent:'#ff7e85', fullWidth:true },
    { icon:'credit-card', label:'ID Card',            value:getDocumentState(profile.id_card_image,profile)==='missing'?'Not ready':'Generated', accent:'#ea580c' },
    { icon:'file',        label:'Appointment Letter', value:getDocumentState(profile.appointment_letter_image,profile)==='missing'?'Not ready':'Generated', accent:'#f97316' },
  ];
  return (
    <View style={ProfileStyles.infoCard}>
      <View style={ProfileStyles.headerStrip}>
        <View style={ProfileStyles.headerLeft}>
          <View style={ProfileStyles.headerIconWrap}><Feather name="user-check" size={15} color="#fff" /></View>
          <View>
            <Text style={ProfileStyles.cardTitle}>Saved Profile</Text>
            <Text style={ProfileStyles.cardSubtitle}>Your current information</Text>
          </View>
        </View>
        <View style={ProfileStyles.memberBadge}><Text style={ProfileStyles.memberBadgeText}>{generateMemberId(profile.email)}</Text></View>
      </View>
      <View style={ProfileStyles.divider} />
      <View style={ProfileStyles.fieldList}>
        {fields.map((f, i) => (
          <View key={f.label} style={[ProfileStyles.fieldRow, f.fullWidth && ProfileStyles.fieldRowFull, i !== fields.length - 1 && ProfileStyles.fieldRowBorder]}>
            <View style={[ProfileStyles.accentBar, { backgroundColor: f.accent }]} />
            <View style={[ProfileStyles.fieldIconWrap, { backgroundColor: f.accent + '18' }]}><Feather name={f.icon} size={14} color={f.accent} /></View>
            <View style={ProfileStyles.fieldContent}>
              <Text style={ProfileStyles.fieldLabel}>{f.label}</Text>
              <Text style={[ProfileStyles.fieldValue, (!f.value || f.value === 'Not ready') && ProfileStyles.fieldValueEmpty]} numberOfLines={f.fullWidth ? 3 : 1}>{f.value || 'Not added yet'}</Text>
            </View>
            <View style={[ProfileStyles.statusDot, { backgroundColor: f.value && f.value !== 'Not ready' ? '#32d27c' : '#e2e5f0' }]} />
          </View>
        ))}
      </View>
      <View style={ProfileStyles.hintRow}> 
        <Feather name="info" size={12} color="#a0a8bf" /> 
        <Text style={ProfileStyles.hintText}>Tap <Text style={ProfileStyles.hintBold}>Update Photo</Text> below to change your profile photo</Text> 
      </View> 
    </View> 
  ); 
} 

export default function ProfileScreen({ navigation }) { 
  const { showToast } = useToast(); 
  const [sidebarVisible, setSidebarVisible] = useState(false); 
  const [activeTab, setActiveTab] = useState('Profile'); 
  const [loading, setLoading] = useState(true); 
  const [saving, setSaving] = useState(false); 
  const [uploading, setUploading] = useState(false); 
  const [isEditing, setIsEditing] = useState(false); 
  const [downloadingDoc, setDownloadingDoc] = useState('');
  const [successMessage, setSuccessMessage] = useState('');
  const [savedProfile, setSavedProfile] = useState(initialForm);
  const [form, setForm] = useState(initialForm);

  const loadCurrentUser = useCallback(async () => {
    setLoading(true);
    const user = await UserStore.getCurrentUser();
    setLoading(false);
    if (!user) { showToast('Please login again.', 'error'); navigation.replace('Login'); return; }
    const rawImage = user.profile_image || '';
    const safeImage = rawImage.startsWith('blob:') ? '' : rawImage;
    const refCode = user.my_referral_code || generateReferralCode(user.email);
    const profileData = {
      name: user.name || '', email: user.email || '', village: user.village || '',
      state: user.state || '', bio: user.bio || '', contact_number: user.contact_number || '',
      phone_number: user.phone_number || '',
      mobile_number: user.mobile_number || user.mobile || user.contact_number || '',
      subscription_type: user.subscription_type || '', profile_image: safeImage,
      role_label: user.role_label || UserStore.getRoleLabel(user.role || 'free'),
      is_subscribed: UserStore.hasActiveSubscription(user),
      id_card_image: user.id_card_image || '', appointment_letter_image: user.appointment_letter_image || '',
      id_card_status: user.id_card_status || '', appointment_letter_status: user.appointment_letter_status || '',
      referral_count: user.referral_count || 0, referral_code: refCode,
    };
    if (rawImage.startsWith('blob:')) await UserStore.updateUser(user.email, { profile_image: '' });
    setSavedProfile(profileData); setForm(profileData);
  }, [navigation, showToast]);

  useFocusEffect(useCallback(() => { loadCurrentUser(); }, [loadCurrentUser])); 
 
  const openEdit = () => { setForm(savedProfile); setIsEditing(true); }; 
  const closeEdit = () => { setForm(savedProfile); setIsEditing(false); }; 
  const handleChange = (k, v) => setForm(p => ({ ...p, [k]: v })); 
  const hasDocumentSubscription = Boolean((isEditing ? form : savedProfile).is_subscribed); 

  const promptSubscriptionRequired = useCallback((documentLabel) => {
    Alert.alert(
      'Subscription Required',
      `${documentLabel} dekhne ke liye subscription lena zaroori hai.`,
      [
        { text: 'Cancel', style: 'cancel' },
        { text: 'Take Subscription', onPress: () => navigation.navigate('Subscription Plans') },
      ]
    );
  }, [navigation]);

  const handleCopyReferralCode = () => {
    const code = savedProfile.referral_code || generateReferralCode(savedProfile.email);
    if (Platform.OS === 'web' && navigator?.clipboard) navigator.clipboard.writeText(code);
    else Clipboard.setString(code);
    showToast('Referral code copied!', 'success');
  };

  const compressImageToBase64 = uri => new Promise((res, rej) => {
    const img = new window.Image(); img.crossOrigin = 'anonymous';
    img.onload = () => { const c = document.createElement('canvas'); c.width = c.height = 200; c.getContext('2d').drawImage(img, 0, 0, 200, 200); res(c.toDataURL('image/jpeg', .5)); };
    img.onerror = rej; img.src = uri;
  });

  const handlePickImage = async () => {
    try {
      setUploading(true);
      if (ImagePicker.requestMediaLibraryPermissionsAsync) {
        const p = await ImagePicker.requestMediaLibraryPermissionsAsync();
        if (!p.granted) { showToast('Gallery permission is required.', 'error'); setUploading(false); return; }
      }
      const r = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], allowsEditing: true, aspect: [1, 1], quality: .5 });
      if (!r.canceled && r.assets?.length) {
        let uri = r.assets[0].uri || '';
        if (typeof document !== 'undefined') uri = await compressImageToBase64(uri);
        handleChange('profile_image', uri);
        showToast('Image selected successfully.', 'success');
      }
    } catch { showToast('Unable to pick image right now.', 'error'); }
    finally { setUploading(false); }
  };

  const handleDownloadDocument = async (type) => {
    const profile = isEditing ? form : savedProfile;
    if (!profile.is_subscribed) {
      promptSubscriptionRequired(type === 'id-card' ? 'ID Card' : 'Appointment Letter');
      return;
    }
    if (!hasDocumentSource(profile)) { showToast('Please complete profile details first.', 'error'); return; }
    try {
      setDownloadingDoc(type);

      let printWindow = null;
      if (Platform.OS === 'web' && typeof window !== 'undefined') {
        printWindow = window.open('', '_blank');
        if (!printWindow) {
          // Popup blocked: fall back to printing in this tab (hidden iframe) below.
        }
        if (printWindow) {
          try {
          printWindow.document.open();
          printWindow.document.write('<!doctype html><html><head><meta charset="utf-8"/><title>Generating…</title></head><body style="font-family:Arial,sans-serif;padding:18px;color:#111827;"><h3 style="margin:0 0 8px 0;">Generating…</h3><div style="color:#6b7280;">Please wait.</div></body></html>');
          printWindow.document.close();
          } catch (_) {}
        }
      }

      const html =
        type === 'id-card'
          ? await buildIdCardHtml(profile, { webPreview: Platform.OS === 'web' && Boolean(printWindow) })
          : await buildAppointmentLetterHtml(profile, { webPreview: Platform.OS === 'web' && Boolean(printWindow) });

      if (Platform.OS === 'web' && printWindow) {
        printWindow.document.open();
        printWindow.document.write(html);
        printWindow.document.close();
        // Avoid printing too early (images may not be decoded yet). Wait for the tab to signal readiness.
        try {
          const start = Date.now();
          const timer = setInterval(() => {
            if (!printWindow || printWindow.closed) { clearInterval(timer); return; }
            const ready = Boolean(printWindow.__PDF_READY__);
            if (ready) {
              clearInterval(timer);
              try { printWindow.focus(); } catch (_) {}
              try { printWindow.print(); } catch (_) {}
              return;
            }
            if (Date.now() - start > 20000) {
              clearInterval(timer);
              try { printWindow.focus(); } catch (_) {}
              showToast('PDF tab is open. Click “Download PDF” in that tab to print/save.', 'success');
            }
          }, 120);
        } catch (_) {}
        showToast('Preparing PDF… print dialog will open. If it doesn’t, use “Download PDF” in the new tab.', 'success');
        return;
      }

      if (Platform.OS === 'web' && typeof document !== 'undefined') {
        const printViaIframe = async (htmlToPrint) => {
          const iframe = document.createElement('iframe');
          iframe.setAttribute('title', 'pdf-print');
          iframe.style.position = 'fixed';
          iframe.style.right = '0';
          iframe.style.bottom = '0';
          iframe.style.width = '0';
          iframe.style.height = '0';
          iframe.style.border = '0';
          iframe.style.opacity = '0';
          document.body.appendChild(iframe);

          const win = iframe.contentWindow;
          const doc = iframe.contentDocument || win?.document;
          if (!win || !doc) throw new Error('iframe not ready');

          doc.open();
          doc.write(htmlToPrint);
          doc.close();

          const waitForImages = async (timeoutMs = 15000) => {
            const start = Date.now();
            while (Date.now() - start < timeoutMs) {
              const imgs = Array.from(doc.images || []);
              const allOk = imgs.every((img) => img.complete && (typeof img.naturalWidth !== 'number' || img.naturalWidth > 0));
              if (allOk) return;
              await new Promise((r) => setTimeout(r, 80));
            }
          };

          await waitForImages();
          try { win.focus(); } catch (_) {}
          win.print();
          setTimeout(() => { try { iframe.remove(); } catch (_) {} }, 1200);
        };

        try {
          await printViaIframe(html);
          showToast('Print dialog opened. Choose "Save as PDF" to download.', 'success');
        } catch (_) {
          showToast('Unable to open print dialog. Please allow popups and try again.', 'error');
        }
        return;
      }

      {
        const a4 = { width: 595, height: 842 };
        let uri = '';
        try {
          ({ uri } = await Print.printToFileAsync({ html, base64: false, ...a4 }));
        } catch (e) {
          // Some Android devices fail when writing PDF data; fall back to system print flow.
          try {
            await Print.printAsync({ html, ...a4 });
            showToast('Print opened. Choose "Save as PDF" to download.', 'success');
            return;
          } catch (_) {
            throw e;
          }
        }
        const safe = (v = '') => String(v || '').trim().replace(/[^a-z0-9-_]+/gi, '-').replace(/-+/g, '-').replace(/(^-|-$)/g, '');
        const namePart = safe(profile?.name) || 'user';
        const filename = `${type === 'id-card' ? 'ID-Card' : 'Appointment-Letter'}-${namePart}.pdf`;

        const trySaveAndroid = async () => {
          try {
            if (Platform.OS !== 'android') return false;
            const SAF = FileSystem.StorageAccessFramework;
            if (!SAF?.requestDirectoryPermissionsAsync || !SAF?.createFileAsync) return false;
            const permissions = await SAF.requestDirectoryPermissionsAsync();
            if (!permissions?.granted) return false;
            const b64 = await FileSystem.readAsStringAsync(uri, { encoding: FileSystem.EncodingType.Base64 });
            const dest = await SAF.createFileAsync(permissions.directoryUri, filename, 'application/pdf');
            await FileSystem.writeAsStringAsync(dest, b64, { encoding: FileSystem.EncodingType.Base64 });
            return true;
          } catch (_) {
            return false;
          }
        };

        const saved = await trySaveAndroid();
        if (saved) {
          showToast('PDF saved successfully.', 'success');
          return;
        }

        const canShare = await Sharing.isAvailableAsync();
        if (canShare) {
          await Sharing.shareAsync(uri, {
            mimeType: 'application/pdf',
            dialogTitle: type === 'id-card' ? 'Save ID Card PDF' : 'Save Appointment Letter PDF',
            UTI: 'com.adobe.pdf',
          });
          showToast('PDF ready! Save or share from the dialog.', 'success');
        } else {
          showToast(`PDF saved: ${uri.split('/').pop()}`, 'success');
        }
      }
    } catch (err) {
      console.error('PDF error:', err);
      showToast('Unable to generate PDF. Please try again.', 'error');
    } finally {
      setDownloadingDoc('');
    }
  };

  const handleSave = async () => { 
    // Restrict updates: users can only update their profile photo from this screen.
    if (form.profile_image === savedProfile.profile_image) {
      showToast('No photo changes to save.', 'info');
      return;
    }
    setSaving(true); 
    const updated = await UserStore.updateUser(form.email, { profile_image: form.profile_image }); 
    setSaving(false); 
    if (!updated) { showToast('Error saving profile.', 'error'); return; } 
    const next = { ...savedProfile, profile_image: updated.profile_image || '' }; 
    setSavedProfile(next); setForm(next); setIsEditing(false); 
    setSuccessMessage('Photo updated successfully.'); 
    setTimeout(() => setSuccessMessage(''), 3000); 
  }; 

  const handleLogout = async () => { await UserStore.clearCurrentUser(); navigation.replace('Login'); };
  const displayProfile = isEditing ? form : savedProfile;
  const referralCode = displayProfile.referral_code || generateReferralCode(displayProfile.email);
  const rank = getRank(displayProfile.referral_count || 0);

  return (
    <View style={ProfileStyles.root}>
      <View style={ProfileStyles.bgOrbPrimary} /><View style={ProfileStyles.bgOrbSecondary} /><View style={ProfileStyles.bgOrbTertiary} />
      <Header title="Profile" onMenuPress={() => setSidebarVisible(true)} onLogout={handleLogout} />
      <ScrollView style={ProfileStyles.scrollView} contentContainerStyle={ProfileStyles.scrollContent} showsVerticalScrollIndicator={false} keyboardShouldPersistTaps="handled">
        <View style={ProfileStyles.profileShell}>
          <View style={ProfileStyles.summaryCard}>
            <View style={ProfileStyles.summaryTopRow}>
              <View style={ProfileStyles.avatarRing}>
                <Image source={displayProfile.profile_image ? { uri: displayProfile.profile_image } : DEFAULT_AVATAR} style={ProfileStyles.avatar} />
                <View style={ProfileStyles.onlineDot} />
              </View>
              <View style={ProfileStyles.summaryContent }>
                <Text style={ProfileStyles.profileName}>{displayProfile.name || 'Your Name'}</Text>
                <Text style={ProfileStyles.profileRole}>RTI News Member</Text>
                <View style={ProfileStyles.summaryRankRow}>
                  <Text style={ProfileStyles.summaryRankEmoji}>{rank.icon}</Text>
                  <Text style={[ProfileStyles.summaryRankText, { color: rank.color }]}>{rank.label}</Text>
                  {displayProfile.state ? (<><Text style={ProfileStyles.summaryDot}>.</Text><MaterialIcons name="location-on" size={13} color="#ff6f91" /><Text style={ProfileStyles.locationText}>{displayProfile.state}</Text></>) : null}
                </View>
              </View>
            </View>
            <View style={ProfileStyles.metricRow}>
              <View>
                <Text style={ProfileStyles.metricLabel}>Profile Completion</Text>
                <Text style={ProfileStyles.metricValuePrimary}>{displayProfile.bio && displayProfile.contact_number && displayProfile.profile_image ? '88%' : '62%'}</Text>
              </View>
              <View style={ProfileStyles.metricRightBlock}>
                <Text style={ProfileStyles.metricLabel}>Member ID</Text>
                <Text style={ProfileStyles.metricValueAccent}>{generateMemberId(displayProfile.email)}</Text>
              </View>
            </View>
            <View style={ProfileStyles.uploadBarCard}> 
              <View style={ProfileStyles.uploadBarTrack}> 
                <View style={ProfileStyles.uploadWaveOne} /><View style={ProfileStyles.uploadWaveTwo} /> 
                <View style={ProfileStyles.uploadDotOne} /><View style={ProfileStyles.uploadDotTwo} /><View style={ProfileStyles.uploadDotThree} /> 
              </View> 
              <View style={ProfileStyles.quickIconRow}> 
                <TouchableOpacity style={ProfileStyles.quickIconButton} onPress={openEdit}> 
                  <Feather name="camera" size={16} color="#ff7e85" /> 
                </TouchableOpacity> 
              </View> 
            </View> 
          </View> 

          {!isEditing && (
            <>
              <RankBadge referralCount={savedProfile.referral_count || 0} />
              <ReferralCodeCard referralCode={referralCode} onCopy={handleCopyReferralCode} />
            </>
          )}

          {isEditing ? ( 
            <View style={ProfileStyles.formCard}> 
              <View style={ProfileStyles.sectionHeaderRow}> 
                <View style={{ flex: 1 }}> 
                  <Text style={ProfileStyles.sectionHeading}>Update Photo</Text> 
                  <Text style={ProfileStyles.sectionSubtitle}>You can only update your profile photo.</Text> 
                  {successMessage ? <Text style={ProfileStyles.successText}>{successMessage}</Text> : null} 
                </View> 
                <TouchableOpacity style={ProfileStyles.uploadPill} onPress={handlePickImage} disabled={uploading}> 
                  <Feather name="image" size={14} color="#6d3df5" /> 
                  <Text style={ProfileStyles.uploadPillText}>{uploading ? 'Opening...' : 'Photo'}</Text> 
                </TouchableOpacity> 
              </View> 
              <View style={ProfileStyles.previewRow}> 
                <Image source={form.profile_image ? { uri: form.profile_image } : DEFAULT_AVATAR} style={ProfileStyles.formPreviewAvatar} /> 
                <View style={ProfileStyles.previewInfo}> 
                  <Text style={ProfileStyles.previewTitle}>Profile Photo</Text> 
                  <Text style={ProfileStyles.helperText}>{form.profile_image ? 'Image selected.' : 'No image selected yet.'}</Text> 
                </View> 
                {form.profile_image ? (<TouchableOpacity style={ProfileStyles.removeMiniButton} onPress={() => handleChange('profile_image', '')}><Feather name="x" size={15} color="#ff7d86" /></TouchableOpacity>) : null} 
              </View> 
              <View style={ProfileStyles.fullWidthGroup}> 
                <Text style={ProfileStyles.inputLabel}>Subscription</Text> 
                <View style={[ProfileStyles.inputWrap, ProfileStyles.inputWrapDisabled]}> 
                  <Feather name="star" size={16} color="#8a94a6" /> 
                  <TextInput
                    style={[ProfileStyles.input, ProfileStyles.inputDisabled]}
                    value={form.role_label ? `${form.role_label} (${form.subscription_type || 'free'})` : (form.subscription_type || 'free')}
                    editable={false}
                  />
                </View>
                {!form.is_subscribed ? (
                  <TouchableOpacity style={[ProfileStyles.uploadPill, { marginTop: 10 }]} onPress={() => navigation.navigate('Subscription Plans')}>
                    <Feather name="credit-card" size={14} color="#6d3df5" />
                    <Text style={ProfileStyles.uploadPillText}>Take Subscription</Text>
                  </TouchableOpacity>
                ) : null} 
              </View> 
              <View style={[ProfileStyles.fullWidthGroup, { marginBottom: 0 }]}> 
                <Text style={ProfileStyles.inputLabel}>Your Referral Code</Text> 
                <View style={[ProfileStyles.inputWrap, ProfileStyles.inputWrapDisabled]}> 
                  <Feather name="share-2" size={16} color="#8a94a6" /> 
                  <TextInput style={[ProfileStyles.input, ProfileStyles.inputDisabled]} value={form.referral_code || generateReferralCode(form.email)} editable={false} />
                </View>
              </View>
              <View style={[ProfileStyles.fullWidthGroup, { marginTop: 10 }]}>
                <RankBadge referralCount={form.referral_count || 0} />
              </View>
              <View style={ProfileStyles.documentSection}>
                <Text style={ProfileStyles.documentSectionTitle}>Documents (Auto Generated)</Text>
                <View style={ProfileStyles.documentRow}>
                  <View style={ProfileStyles.documentInfo}><Feather name="credit-card" size={20} color="#ea580c" /><Text style={ProfileStyles.documentLabel}>ID Card</Text></View>
                  <Text style={ProfileStyles.autoDocHint}>PDF Download</Text>
                </View>
                {hasDocumentSource(form) && hasDocumentSubscription ? (
                  <>
                    <AutoIdCardPreview profile={form} />
                    <TouchableOpacity style={ProfileStyles.generatedDownloadBtn} onPress={() => handleDownloadDocument('id-card')} disabled={downloadingDoc === 'id-card'}>
                      <Feather name="download" size={16} color="#fff" />
                      <Text style={ProfileStyles.generatedDownloadText}>{downloadingDoc === 'id-card' ? 'Generating PDF...' : 'Download ID Card (PDF)'}</Text>
                    </TouchableOpacity>
                  </>
                ) : hasDocumentSource(form) ? (
                  <>
                    <Text style={ProfileStyles.helperText}>Subscription lene ke baad hi ID Card dekh sakte hain.</Text>
                    <TouchableOpacity style={ProfileStyles.generatedDownloadBtn} onPress={() => promptSubscriptionRequired('ID Card')}>
                      <Feather name="lock" size={16} color="#fff" />
                      <Text style={ProfileStyles.generatedDownloadText}>Take Subscription</Text>
                    </TouchableOpacity>
                  </>
                ) : <Text style={ProfileStyles.helperText}>Complete profile to generate ID Card.</Text>}
                <View style={ProfileStyles.documentSpacer} />
                <View style={ProfileStyles.documentRow}>
                  <View style={ProfileStyles.documentInfo}><Feather name="file" size={20} color="#f97316" /><Text style={ProfileStyles.documentLabel}>Appointment Letter</Text></View>
                  <Text style={ProfileStyles.autoDocHint}>PDF Download</Text>
                </View>
                {hasDocumentSource(form) && hasDocumentSubscription ? (
                  <>
                    <AutoAppointmentLetterPreview profile={form} />
                    <TouchableOpacity style={[ProfileStyles.generatedDownloadBtn, ProfileStyles.generatedDownloadBtnAlt]} onPress={() => handleDownloadDocument('appointment-letter')} disabled={downloadingDoc === 'appointment-letter'}>
                      <Feather name="download" size={16} color="#fff" />
                      <Text style={ProfileStyles.generatedDownloadText}>{downloadingDoc === 'appointment-letter' ? 'Generating PDF...' : 'Download Appointment Letter (PDF)'}</Text>
                    </TouchableOpacity>
                  </>
                ) : hasDocumentSource(form) ? (
                  <>
                    <Text style={ProfileStyles.helperText}>Subscription lene ke baad hi Appointment Letter dekh sakte hain.</Text>
                    <TouchableOpacity style={[ProfileStyles.generatedDownloadBtn, ProfileStyles.generatedDownloadBtnAlt]} onPress={() => promptSubscriptionRequired('Appointment Letter')}>
                      <Feather name="lock" size={16} color="#fff" />
                      <Text style={ProfileStyles.generatedDownloadText}>Take Subscription</Text>
                    </TouchableOpacity>
                  </>
                ) : null}
              </View> 
              <View style={ProfileStyles.formFooterRow}> 
                <TouchableOpacity style={ProfileStyles.cancelButton} onPress={closeEdit}><Text style={ProfileStyles.cancelButtonText}>Cancel</Text></TouchableOpacity> 
                <TouchableOpacity style={ProfileStyles.submitButton} onPress={handleSave} disabled={saving}><Text style={ProfileStyles.submitButtonText}>{saving ? 'Saving...' : 'Save Photo'}</Text></TouchableOpacity> 
              </View> 
            </View> 
          ) : ( 
            <SavedProfileCard profile={savedProfile} /> 
          )} 
        </View>
        {loading ? <Text style={ProfileStyles.loadingText}>Loading profile...</Text> : null}
      </ScrollView>

      {!isEditing && ( 
        <View style={ProfileStyles.stickyActionWrap}> 
          <View style={ProfileStyles.stickyActionCard}> 
            <Text style={ProfileStyles.actionTitle}>Actions</Text> 
            <View style={ProfileStyles.actionRow}> 
              <TouchableOpacity style={[ProfileStyles.actionButton, ProfileStyles.updateButton]} onPress={openEdit} disabled={saving}> 
                <Feather name="camera" size={16} color="#fff" /><Text style={ProfileStyles.actionButtonText}>Update Photo</Text> 
              </TouchableOpacity> 
            </View> 
          </View> 
        </View> 
      )} 

      <Footer activeTab={activeTab} onTabPress={setActiveTab} />
      <Sidebar visible={sidebarVisible} onClose={() => setSidebarVisible(false)} activeItem="Profile" />
    </View>
  );
}










